import {DATA} from './data.js?v=0.90.48';
import {startingMoveIds} from './moveset-identity.js?v=0.90.48';
import {initializeProgress} from './progression.js?v=0.90.41';
import {FINALE_TRAINERS,PEACH_FINAL,LEGACY_POOLS,COMMISSIONS} from './finale-data.js?v=0.90.48';
export function finaleState(s){const q=s.finale??={version:1,burialCursor:0,buried:false,legacies:null,quests:{},unique:{},commissions:[],gallerySeen:[]};q.quests??={};q.unique??={};q.commissions??=[];q.gallerySeen??=[];return q;}
export const finaleUnlocked=s=>Boolean(s.fates?.['LDR-06']&&s.botrune?.walterCalmed);
export function finishBurialLine(s,index){const q=finaleState(s);if(q.buried||q.burialCursor!==index||index<0||index>=14)return false;q.burialCursor++;if(q.burialCursor===14){q.buried=true;q.mirrorRumour=true;s.storyHistory??=[];if(!s.storyHistory.some(e=>e.id==='FN-TREE-BURIAL-20261021'))s.storyHistory.push({id:'FN-TREE-BURIAL-20261021',place:'Willowmere',people:['CHR-PATE','CHR-TRADE']});}return true;}
export function grantMemorialPartners(s,create,random=Math.random){const q=finaleState(s);if(!q.buried||q.legacies)return false;const picks={};for(const key of ['pate','trade']){const pool=LEGACY_POOLS[key];const id=pool[Math.min(pool.length-1,Math.floor(random()*pool.length))];const u=create(id,1,'memorial-'+key);u.originalStarter=false;u.lives=1;u.giftOrigin=(key==='pate'?'Pate':'Trade')+'’s travelling partner';u.memorialLegacy={version:1,from:key==='pate'?'CHR-PATE':'CHR-TRADE',growthBonus:15};u.level=80;initializeProgress(u);u.moves=memorialMoves(u);u.memorialLegacy.movesVersion=1;(s.party.length<6?s.party:s.reserve).push(u);picks[key]={uid:u.uid,speciesId:id};}q.legacies=picks;return true;}
export function peachQuest(s,key){return finaleState(s).quests[key]??={accepted:false,read:false,order:[],weights:[0,0,0],solved:false};}
export function acceptPeachQuest(s,key){if(!['guan','fei'].includes(key)||!finaleState(s).buried)return false;const q=peachQuest(s,key);if(q.accepted)return false;q.accepted=true;return true;}
export function readPeachClue(s,key){const q=peachQuest(s,key);if(!q.accepted||q.read)return false;q.read=true;return true;}
export function turnOathRune(s,rune){const q=peachQuest(s,'guan');if(!q.accepted||!q.read||q.solved||!['shelter','faith','crossing'].includes(rune))return false;if(q.order.length===3)q.order=[];q.order.push(rune);if(q.order.length===3&&q.order.join(',')==='shelter,faith,crossing')q.solved=true;return true;}
export function turnBridgeWeight(s,index){const q=peachQuest(s,'fei');if(!q.accepted||!q.read||q.solved||![0,1,2].includes(index))return false;q.weights[index]=(q.weights[index]+1)%4;q.solved=q.weights.join(',')==='1,3,2';return true;}
export function canMeetFinalUnique(s,key){const q=finaleState(s),spec=PEACH_FINAL[key];if(!spec||q.unique[key])return false;if([...(s.party||[]),...(s.reserve||[]),...(s.dead||[])].some(u=>u.species?.id===spec.id||(key==='suncub'&&u.species?.id==='187')))return false;if(key==='crux')return Boolean(q.dariusDefeated);if(['gehennuar','suncub'].includes(key))return Boolean(s.fates?.['LDR-07']&&q.rareRecords?.includes(key));const p=peachQuest(s,key);return p.accepted&&p.solved&&(s.defeatedTrainers||[]).includes(spec.guard);}
export function finalUniqueEncounter(s,key){if(!canMeetFinalUnique(s,key))return null;return {speciesId:PEACH_FINAL[key].id,level:PEACH_FINAL[key].level,seed:'finale-unique-'+key,finaleUnique:key,phase:'DAY',tableId:'FINALE-UNIQUE-'+key.toUpperCase()};}
export function settleFinalUnique(s,key,outcome){if(!['captured','defeated'].includes(outcome)||!PEACH_FINAL[key]||finaleState(s).unique[key])return false;finaleState(s).unique[key]=outcome;return true;}
export function canFightFinale(s,id){const q=finaleState(s);if(id==='LDR-07')return q.buried;if(id==='LDR-08')return Boolean(q.dariusDefeated);if(id==='TRN-FN-DARIUS')return Boolean(s.fates?.['LDR-07']&&!q.dariusDefeated);if(id==='TRN-FN-GUAN')return peachQuest(s,'guan').accepted;if(id==='TRN-FN-FEI')return peachQuest(s,'fei').accepted;return true;}
export function settleFinalLeader(s,id,fate){if(!['LDR-07','LDR-08'].includes(id)||!['SPARED','EXECUTED'].includes(fate)||s.fates?.[id]||s.pendingFate?.id!==id)return false;s.fates??={};s.fates[id]=fate;s.pendingFate=null;const q=finaleState(s);if(id==='LDR-07'){q.mirrorLead=true;q.angerChoice=fate==='SPARED'?'restrained':'followed';}else q.gateRevealed=true;return true;}
export function settleDariusFinale(s){const q=finaleState(s);if(q.dariusDefeated)return false;q.dariusDefeated=true;q.dariusFollowup=true;s.defeatedTrainers??=[];if(!s.defeatedTrainers.includes('TRN-FN-DARIUS'))s.defeatedTrainers.push('TRN-FN-DARIUS');return true;}
export function createCommission(s,uid,choices){const q=finaleState(s),u=s.party.find(u=>u.uid===uid&&u.hp>0&&!u.dead);if(!u||!['river','sunset','earth'].includes(choices.palette)||!['open','gather','rise'].includes(choices.shape)||!['wash','stamp','etch'].includes(choices.tool))return null;const affinity={river:['WATER','ICE','GRASS'],sunset:['FIRE','ELECTRIC','FAIRY'],earth:['GROUND','ROCK','STEEL']},artistTypes=[...u.species.types],partnerAffinity=artistTypes.some(t=>affinity[choices.palette].includes(t));const n=q.commissions.length,brief=COMMISSIONS[n%COMMISSIONS.length],score=Object.keys(choices).reduce((v,k)=>v+(brief[k]===choices[k]?1:0),0),work={id:'commission-'+(n+1),number:n+1,uid,artist:u.nickname||u.species.name,speciesId:u.species.id,title:brief.title,artistTypes,partnerAffinity,...choices,score,reward:350+score*150+(partnerAffinity?100:0)};q.commissions.push(work);s.money=(s.money||0)+work.reward;if((n+1)%3===0)s.heartyFood=(s.heartyFood||0)+1;return work;}
export function finaleObjective(s,room){const q=finaleState(s);if(room==='burialGrove'&&!q.buried)return {spot:'fn-burial',text:'Meet Walter beneath the old tree · bury Pate and Trade'};if(room.startsWith('sun')||room==='burialGrove')return {spot:room+'-forward',text:q.buried?'Follow the river east to Cayfen. Side paths lead to the two Peach Grove guardians.':'Follow Willowmere to the old tree. Walter has taken the wagon ahead.'};if(room.startsWith('guan')||room.startsWith('fei')){const key=room.startsWith('guan')?'guan':'fei',p=peachQuest(s,key),spec=PEACH_FINAL[key];return {spot:!p.accepted?'fn-'+key+'-keeper':!p.read?'fn-'+key+'-clue':!s.defeatedTrainers?.includes(spec.guard)?spec.guard:!p.solved?key==='guan'?'fn-guan-rune-shelter':'fn-fei-weight-0':'fn-'+key+'-encounter',text:!p.accepted?'Speak to the crossing keeper to begin '+spec.title:!p.read?'Read the shrine inscription before using its mechanism':!s.defeatedTrainers?.includes(spec.guard)?'Defeat the company blocking the crossing':!p.solved?'Use the recorded clue to restore the crossing mechanism':q.unique[key]?'The guardian’s unique encounter is recorded. Return to Willowmere.':'Approach '+spec.name+' when your expedition is ready'};}
 if(room.startsWith('cayfen'))return {spot:s.fates?.['LDR-07']?'cayfen-forward':room==='cayfenHall'?'LDR-07':'cayfenHall',text:s.fates?.['LDR-07']?'The mirror records point to Hasan in Ramelle. Prepare in Cayfen before crossing Sporefall.':'Visit Cayfen’s gallery and face Marshal Ibrahim in the Sun Hall · partners around Lv. 90'};
 if(room.startsWith('spore'))return {spot:q.dariusDefeated?(q.unique.crux?'sporeCrown-forward':'fn-crux-encounter'):room==='sporeCrown'?'fn-darius':room+'-forward',text:q.dariusDefeated?'Darius’s final company is broken. Cruxwyrm is free; Ramelle lies beyond the crossing.':'Cross Sporefall towards Ramelle. Both armies are retreating from the last crossing.'};
 if(room.startsWith('ramelle')||room==='afterlifeThreshold')return {spot:q.gateRevealed?'fn-afterlife':room==='ramelleFortress'?'LDR-08':'ramelleFortress',text:q.gateRevealed?'The mirror beneath the fortress is open. The descent begins in a future chapter.':'Face Hasan in the alabaster fortress · Lv. 100–105. He will show you the way below.'};return null;}
export function finaleJournal(s,room){if(!finaleObjective(s,room))return '';const q=finaleState(s);return finaleObjective(s,room).text+' '+(q.buried?'Pate and Trade rest beneath the Remembering Tree. Walter has heard a story about a mirror that answers the living; he cannot promise what it means.':'Walter has arranged to bury your friends beside the Willowmere.')+' '+['guan','fei'].map(k=>PEACH_FINAL[k].name+': '+(q.unique[k]||(q.quests[k]?.accepted?(q.quests[k].solved?'crossing restored':'investigating'):''))).filter(v=>!v.endsWith(': ')).join(' · ');}

export function finaleSpots(s,room,spots){if(!/^(sun|burial|guan|fei|cayfen|spore|ramelle|afterlife)/.test(room))return spots;const q=finaleState(s);return spots.filter(p=>!(p.id==='fn-darius'&&q.dariusDefeated)&&!(p.id==='fn-hasan-ally'&&q.dariusDefeated&&!q.dariusFollowup)&&!(['LDR-07','LDR-08'].includes(p.id)&&s.fates?.[p.id]==='EXECUTED'));}

function memorialMoves(u){return startingMoveIds(DATA,u.species,u.level).map(id=>{const m=DATA.moves.find(m=>m.id===id);return {...m,left:m.pp};});}
export function migrateMemorialMoves(s){let changed=false;for(const u of [...s.party||[],...s.reserve||[]]){if(u.dead||u.hp<=0||u.level<80||u.memorialLegacy?.version!==1||u.memorialLegacy.movesVersion===1)continue;const initial=startingMoveIds(DATA,u.species,1),current=(u.moves||[]).map(m=>m.id);if(initial.length===current.length&&initial.every(id=>current.includes(id)))u.moves=memorialMoves(u);u.memorialLegacy.movesVersion=1;changed=true;}return changed;}
